from __future__ import annotations
from typing import Dict, Tuple

Cell = Tuple[int, int]

def enumerate_transverse_cells(d: int, e: int) -> Dict[Cell, int]:
    """Enumerate the d-by-e transverse model with unit multiplicity."""
    if d < 0 or e < 0:
        raise ValueError("degrees must be nonnegative")
    return {(i, j): 1 for i in range(d) for j in range(e)}

def bezout_total(d: int, e: int) -> int:
    """Return the transverse weighted intersection number."""
    if d < 0 or e < 0:
        raise ValueError("degrees must be nonnegative")
    return d * e
